 function updatePreview(){P.draw($('#doll-preview'),state);window.LoveMotion?.mount($('#doll-preview'),()=>state);$('#scene').className='scene scene-'+state.background;P.mountScene?.($('#scene'),state.background);let specials=$('#scene-specials');if(!specials){specials=document.createElement('div');specials.id='scene-specials';specials.className='scene-specials';specials.setAttribute('aria-label','คอลเลกชันพิเศษ');$('#scene').prepend(specials);}specials.innerHTML=sceneSpecials(state);specials.hidden=!specials.childElementCount;$('#doll-name-label').textContent=state.name.trim()||P.animals.find(a=>a.id===state.animal).nickname;$('#summary-animal').textContent=P.animals.find(a=>a.id===state.animal).name;$('#summary-outfit').textContent=state.outfit==='custom'?'เสื้อที่วาดด้วยใจ':P.outfits.find(a=>a.id===state.outfit).name;$('#summary-flower').textContent=state.flowers.map(f=>P.flowers.find(x=>x.id===f.id).name).join(' + ');$('#preview-caption').textContent=step<3?'เจ้าตัวเล็กพร้อมรับความในใจของคุณแล้ว':state.to?`เตรียมกอดอุ่น ๆ ไปให้ ${state.to}`:'เจ้าตัวเล็กพร้อมรับความในใจของคุณแล้ว';}
