 function songUrl(raw){if(!raw.trim())return null;try{const u=new URL(raw);const hosts=['youtube.com','www.youtube.com','m.youtube.com','music.youtube.com','youtu.be','open.spotify.com'];if(u.protocol!=='https:'||!hosts.includes(u.hostname)||u.username||u.password||u.port)return null;return u.href;}catch{return null;}}
 function validate(){const errors={};for(const f of ['from','to','title','message'])if(!state[f].trim())errors[f]='กรุณาใส่'+({from:'ชื่อผู้ส่ง',to:'ชื่อคนรับ',title:'หัวข้อจดหมาย',message:'ข้อความจากใจ'}[f]);if(chars(state.message).length>100)errors.message='ข้อความต้องไม่เกิน 100 ตัวอักษร';if(state.musicUrl.trim()&&!songUrl(state.musicUrl))errors.musicUrl='ใช้ลิงก์ https:// ของ YouTube หรือ open.spotify.com เท่านั้น';if(state.musicUrl.trim()&&!state.songTitle.trim())errors.songTitle='ใส่ชื่อเพลงเพื่อแสดงในภาพสตอรี่';if(state.songTitle.trim()&&!state.musicUrl.trim())errors.musicUrl='ใส่ลิงก์สำหรับฟังเพลง หรือเว้นชื่อเพลงไว้';if(Object.keys(errors).length){step=3;render();Object.entries(errors).forEach(([f,msg])=>{const err=$('#error-'+f);if(err)err.textContent=msg;const el=$(`[data-field="${f}"]`);if(el){el.classList.add('invalid');el.setAttribute('aria-invalid','true');}});$(`[data-field="${Object.keys(errors)[0]}"]`)?.focus();toast('เติมความในใจอีกนิดก่อนส่งนะ');return false;}return true;}
 async function go(target){if(target>=4&&!validate())return;if(target===5){const b=$('#next');b.disabled=true;b.textContent='กำลังเก็บความในใจ…';try{const fingerprint=JSON.stringify(normalize(state));if(!sharedGift||!sharedGift.active||new Date(sharedGift.expiresAt)<=new Date()||sharedGift.fingerprint!==fingerprint||sharedGift.plan!==giftPlan){const result=await C.createGift(normalize(state),giftPlan);if(JSON.stringify(normalize(state))!==fingerprint)throw new Error('บันทึกแล้ว แต่แบบร่างมีการเปลี่ยนแปลง กรุณาตรวจอีกครั้ง');if(result.pending){b.disabled=false;render();return;}sharedGift={...result,fingerprint,plan:giftPlan};}}catch(e){toast(e.message);b.disabled=false;render();return;}b.disabled=false;}step=target;render();if(innerWidth<621)$('#step-title').scrollIntoView({behavior:'smooth',block:'start'});}
