   if(b.id==='copy-manage-link'){try{await navigator.clipboard.writeText(sharedGift.manageUrl);toast('คัดลอกลิงก์จัดการส่วนตัวแล้ว เก็บไว้กับคุณเท่านั้นนะ');}catch{const input=$('#gift-manage-link');input.focus();input.select();}}
